ee:message.ee:set-payload:
%dw 2.0
output application/json

// ================= VARIABLES =================

var currencyParam = vars.currencyQP default null
var invoiceId     = vars.id default null

// ================= FUNCTION =================

// Fonction pour convertir epoch seconds -> DateTime ISO
fun toDateTime(epoch) =
    (epoch as Number) as DateTime {unit: "seconds"}

// ✅ Ton mapping EXACT, inchangé
fun mapInvoice(invoiceWrapper) = do {

    var inv = invoiceWrapper.data
    var lines = inv.lines.data default []

    ---
    {
        id: inv.id,

        total: 
            (lines map $.amount)
                reduce ((item, acc = 0) -> acc + item),

        currency: upper(inv.currency),

        date: toDateTime(inv.created),

        customer: {
            id: inv.customer,
            name: inv.customer_name,
            email: inv.customer_email,
            phone: inv.customer_phone,
            city: inv.customer_address.city,
            country: inv.customer_address.country,
            postalCode: inv.customer_address.postal_code
        },

        lineItems: 
            lines map (line) -> {
                id: line.id,
                amount: line.amount
            }
    }
}

//
// ================= FILTRAGE =================
//

var safePayload =
    if (payload is Array)
        payload
    else
        []

var afterCurrency =
    if (currencyParam == null)
        safePayload
    else
        safePayload filter (
            upper($.data.currency) == upper(currencyParam)
        )

var afterId =
    if (invoiceId == null)
        afterCurrency
    else
        afterCurrency filter (
            $.data.id as String == invoiceId as String
        )

//
// ================= OUTPUT =================
//

---
if (invoiceId != null)
    if (isEmpty(afterId))
        null
    else
        mapInvoice(afterId[0])
else
    afterId map (item) -> mapInvoice(item)
